// Weekly audit of MEL's own development, not of its capabilities: which
// models really write the code, whether a model is silently excluded,
// whether missions are delivered or loop. Every finding becomes a repair
// mission through the self-audit supervisor, so MEL fixes what it measures.

import { mentorMetrics, pipelineAlerts } from '../evolution/autonomy-metrics.js';
import { standardRegistry } from '../models/ModelRegistry.js';
import { createDefaultAugmentioPool } from '../augmentio/default-pool.js';
import { ZeroEuroGovernor } from '../augmentio/zero-euro-governor.js';

const WEEK_MS = 7 * 24 * 60 * 60 * 1000;
const obj = value => {
  if (value && typeof value === 'object') return value;
  try { return JSON.parse(value || '{}') || {}; } catch { return {}; }
};

/** Code-specialised Workers AI models the governor would refuse at runtime. */
export function excludedCodeModels(env, { registry = standardRegistry } = {}) {
  const wanted = registry.list().filter(model => (model.capabilities || []).includes('CODE_SPECIALIST')).map(model => model.id);
  const governor = new ZeroEuroGovernor({ maxCost: 0 });
  // The governor decision needs no inference: a stub binding is enough here.
  const poolEnv = env?.AI?.run ? env : { ...env, AI: { run: async () => null } };
  const allowed = new Set(createDefaultAugmentioPool(poolEnv, { registry }).list({ capability: 'CODE_SPECIALIST' })
    .filter(provider => governor.allows(provider)).map(provider => provider.modelId));
  return wanted.filter(id => !allowed.has(id));
}

// Each code model gets a small real exercise: the answer must define the
// requested function and pass it. Proves the model still answers usable code.
const PROBE = 'Écris uniquement une fonction JavaScript nommée sumEven(list) qui renvoie la somme des nombres pairs du tableau list. Réponds avec le code seul.';
export async function probeCodeModels(env, { registry = standardRegistry, timeoutMs = 60_000 } = {}) {
  if (!env?.AI?.run) return [];
  const models = registry.list().filter(model => (model.capabilities || []).includes('CODE_SPECIALIST'));
  return Promise.all(models.map(async model => {
    const started = Date.now();
    try {
      let timer;
      const timeout = new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error('PROBE_TIMEOUT')), timeoutMs);
      });
      let out;
      try {
        out = await Promise.race([
          env.AI.run(model.id, { messages: [{ role: 'user', content: PROBE }], max_tokens: 800 }),
          timeout,
        ]);
      } finally {
        clearTimeout(timer);
      }
      const text = String(out?.response ?? out?.choices?.[0]?.message?.content ?? out?.output_text ?? '');
      const code = (text.match(/```(?:js|javascript)?\s*([\s\S]*?)```/) || [null, text])[1];
      // eslint-disable-next-line no-new-func
      const sumEven = new Function(code + '\nreturn typeof sumEven === "function" ? sumEven : null;')();
      const passed = typeof sumEven === 'function' && sumEven([1, 2, 3, 4, 7, 10]) === 16 && sumEven([]) === 0;
      return { model: model.id, passed, ms: Date.now() - started };
    } catch (error) {
      return { model: model.id, passed: false, ms: Date.now() - started, error: String(error?.message || error).slice(0, 80) };
    }
  }));
}

export function auditDevelopment({ jobs = [], env = {}, registry = standardRegistry, now = Date.now(), maxAutonomy = true, probes = [] } = {}) {
  // Exclude future timestamps and duplicate snapshots of the same durable job.
  // Different job ids for the same roadmap objective remain distinct attempts.
  const seenJobs = new Set();
  const week = jobs.filter(job => {
    const updated = Number(job?.updated_at || 0);
    return Number.isFinite(updated) && updated >= now - WEEK_MS && updated <= now;
  }).sort((a, b) => Number(b.updated_at) - Number(a.updated_at)).filter(job => {
    const id = String(job?.id || '');
    if (!id) return true;
    if (seenJobs.has(id)) return false;
    seenJobs.add(id);
    return true;
  });
  const findings = [];
  const findingKeys = new Set();
  const add = (code, detail) => {
    const finding = { code, detail: String(detail).slice(0, 300) };
    const key = JSON.stringify(finding);
    if (!findingKeys.has(key)) { findings.push(finding); findingKeys.add(key); }
  };

  const specialists = new Set(registry.list().filter(model => (model.capabilities || []).includes('CODE_SPECIALIST')).map(model => 'workers-ai:' + model.id));
  const metrics = mentorMetrics(week);
  const generalist = metrics.models.filter(model => model.selected > 0 && !specialists.has(model.provider));
  if (generalist.length) add('MENTOR_CODED_WITH_NON_CODE_MODEL', generalist.map(model => model.provider + ' ×' + model.selected).join(', '));

  const excluded = excludedCodeModels(env, { registry });
  if (excluded.length) add('CODE_MODEL_EXCLUDED_BY_ZERO_COST_PROOF', excluded.join(', '));

  for (const alert of pipelineAlerts(week, metrics, { now })) {
    if (alert.code === 'MENTOR_MODEL_NEVER_SELECTED') add(alert.code, alert.provider + ' (' + alert.attempts + ' tentatives)');
    if (alert.code === 'REPEATED_REJECTION') add(alert.code, alert.cause + ' ×' + alert.count);
  }
  const broken = probes.filter(probe => !probe.passed);
  if (broken.length) add('CODE_MODEL_PROBE_FAILED', broken.map(probe => probe.model + (probe.error ? ' (' + probe.error + ')' : '')).join(', '));
  const stalled = pipelineAlerts(week, metrics, { now }).filter(alert => alert.code === 'JOB_STALLED');
  if (stalled.length) add('JOBS_STALLED', stalled.map(alert => alert.job_id).slice(0, 5).join(', '));

  const deliveredStatuses = new Set(['COMPLETED', 'DONE', 'DONE_VERIFIED', 'VERIFIED', 'ACCEPTED']);
  const completed = week.filter(job => deliveredStatuses.has(String(job?.status).toUpperCase())).length;
  const councilRejected = week.filter(job => /COUNCIL_REJECTED/.test(String(job?.error || ''))).length;
  const failed = week.filter(job => String(job?.status).toUpperCase() === 'FAILED').length;
  if (maxAutonomy && week.length && completed === 0) add('NO_DELIVERY_THIS_WEEK', week.length + ' missions, 0 livrée, ' + failed + ' en échec');
  if (councilRejected > completed) add('COUNCIL_REJECTS_MORE_THAN_DELIVERED', councilRejected + ' refus pour ' + completed + ' livraisons');

  // Same roadmap item retried over and over: the mission loops instead of progressing.
  const tries = {};
  for (const job of week) {
    const id = obj(job?.optional_context).roadmap_id;
    if (id) tries[id] = (tries[id] || 0) + 1;
  }
  const loops = Object.entries(tries).filter(([, count]) => count >= 4);
  if (loops.length) add('MISSION_LOOP', loops.map(([id, count]) => id + ' ×' + count).join(', '));

  return {
    ok: findings.length === 0,
    status: findings.length ? 'DEVELOPMENT_AUDIT_FAILED' : 'DEVELOPMENT_AUDIT_OK',
    findings,
    probes,
    summary: {
      jobs: week.length, completed, failed,
      blocked: week.filter(job => ['BLOCKED', 'WAITING_DEPENDENCY'].includes(String(job?.status || '').toUpperCase())).length,
      repeated_objectives: loops.length,
      council_rejected: councilRejected, models: metrics.models.length,
    },
  };
}

/**
 * Durable weekly evidence for MEL-AUDIT-02. This records observations only:
 * no status transitions, roadmap admissions or repair dispatches. A repeated
 * invocation updates the same weekly report and cannot duplicate findings.
 */
export async function persistWeeklyDevelopmentAudit(db, report, { now = Date.now() } = {}) {
  if (!db?.prepare || !report || !Array.isArray(report.findings)) {
    throw Object.assign(new Error('DEVELOPMENT_AUDIT_PERSIST_INPUT_REQUIRED'), { code: 'DEVELOPMENT_AUDIT_PERSIST_INPUT_REQUIRED' });
  }
  const at = Number(now);
  if (!Number.isFinite(at)) throw Object.assign(new Error('DEVELOPMENT_AUDIT_TIME_INVALID'), { code: 'DEVELOPMENT_AUDIT_TIME_INVALID' });
  // ISO-style UTC weeks begin Monday; 1970-01-05 was the first Monday.
  const mondayOffset = 4 * 24 * 60 * 60 * 1000;
  const weekStart = Math.floor((at - mondayOffset) / WEEK_MS) * WEEK_MS + mondayOffset;
  await db.prepare(`CREATE TABLE IF NOT EXISTS mel_development_audit_reports (
    week_start INTEGER PRIMARY KEY, report_json TEXT NOT NULL, updated_at INTEGER NOT NULL
  )`).run();
  await db.prepare(`CREATE TABLE IF NOT EXISTS mel_development_audit_findings (
    week_start INTEGER NOT NULL, code TEXT NOT NULL, detail TEXT NOT NULL,
    PRIMARY KEY (week_start, code, detail)
  )`).run();
  const distinct = new Map();
  for (const finding of report.findings) {
    const code = String(finding?.code || '').slice(0, 120);
    if (!code) continue;
    const detail = String(finding?.detail || '').slice(0, 300);
    distinct.set(JSON.stringify([code, detail]), { code, detail });
  }
  // The weekly report is a snapshot, not an append-only finding ledger.
  // A resolved finding must disappear from this week's durable snapshot;
  // otherwise retries report an obsolete failure even after MAX fixes it.
  const writes = [
    db.prepare(`INSERT INTO mel_development_audit_reports(week_start,report_json,updated_at)
      VALUES(?,?,?) ON CONFLICT(week_start) DO UPDATE SET
        report_json=excluded.report_json, updated_at=excluded.updated_at`)
      .bind(weekStart, JSON.stringify(report), at),
    db.prepare('DELETE FROM mel_development_audit_findings WHERE week_start=?').bind(weekStart),
    ...[...distinct.values()].map(({ code, detail }) =>
      db.prepare(`INSERT INTO mel_development_audit_findings(week_start,code,detail)
        VALUES(?,?,?) ON CONFLICT(week_start,code,detail) DO NOTHING`)
        .bind(weekStart, code, detail)),
  ];
  // D1 batches are transactional: publish the replacement snapshot together,
  // never expose a new report with stale findings if a write fails.
  if (typeof db.batch === 'function') await db.batch(writes);
  else for (const statement of writes) await statement.run();
  return { persisted: true, week_start: weekStart, findings_recorded: distinct.size };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { auditDevelopment, excludedCodeModels, probeCodeModels, persistWeeklyDevelopmentAudit } from '../src/diagnostics/development-audit.js';
import { standardRegistry } from '../src/models/ModelRegistry.js';
import { createDefaultAugmentioPool } from '../src/augmentio/default-pool.js';

const NOW = Date.parse('2026-10-24T10:00:00Z');
const job = (over) => ({ requested_by: 'mel-autonomy', updated_at: NOW - 3600_000, status: 'QUEUED', ...over });
const council = (selected) => ({ result_json: { bridge_preparation: { mentor: { council: { providers_attempted: [selected], selected_provider: selected, rejected_proposals: [] } } } } });

test('the weekly audit flags code written by a generalist model and a week without delivery', () => {
  const report = auditDevelopment({ now: NOW, jobs: [job(council('workers-ai:@cf/meta/llama-3.3-70b-instruct-fp8-fast'))] });
  const codes = report.findings.map(f => f.code);
  assert.equal(report.ok, false);
  assert.ok(codes.includes('MENTOR_CODED_WITH_NON_CODE_MODEL'));
  assert.ok(codes.includes('NO_DELIVERY_THIS_WEEK'));
});

test('a code model missing from the zero-cost proof is reported, not silently dropped', t => {
  const saved = process.env.MEL_TEST_VERIFIED_ZERO_COST_PROVIDERS;
  delete process.env.MEL_TEST_VERIFIED_ZERO_COST_PROVIDERS;
  t.after(() => { if (saved !== undefined) process.env.MEL_TEST_VERIFIED_ZERO_COST_PROVIDERS = saved; });
  assert.ok(excludedCodeModels({}).includes('@cf/qwen/qwen2.5-coder-32b-instruct'));
  const report = auditDevelopment({ now: NOW, jobs: [] });
  assert.ok(report.findings.some(f => f.code === 'CODE_MODEL_EXCLUDED_BY_ZERO_COST_PROOF'));
});

test('a mission retried four times in a week is a loop', () => {
  const jobs = Array.from({ length: 4 }, () => job({ status: 'FAILED', optional_context: { roadmap_id: 'MEL-X' } }));
  assert.ok(auditDevelopment({ now: NOW, jobs }).findings.some(f => f.code === 'MISSION_LOOP' && f.detail.includes('MEL-X ×4')));
});

test('each code model is really tested on a small exercise', async () => {
  const env = { AI: { async run(model) {
    if (model.includes('gpt-oss-120b')) return { response: 'pas de code' };
    return { response: '```js\nfunction sumEven(list){return list.filter(n=>n%2===0).reduce((a,b)=>a+b,0)}\n```' };
  } } };
  const probes = await probeCodeModels(env);
  assert.equal(probes.length, 2);
  assert.equal(probes.find(p => p.model.includes('gpt-oss-120b')).passed, false);
  assert.ok(probes.filter(p => !p.model.includes('gpt-oss-120b')).every(p => p.passed));
  const report = auditDevelopment({ now: NOW, jobs: [], probes });
  assert.ok(report.findings.some(f => f.code === 'CODE_MODEL_PROBE_FAILED' && f.detail.includes('gpt-oss-120b')));
});

test('MAX codes only with code models: small ones first, large ones after three failures', () => {
  const pool = createDefaultAugmentioPool({ AI: { run: async () => null } });
  const specialists = pool.list({ capability: 'CODE_SPECIALIST' }).map(p => p.modelId);
  assert.deepEqual(specialists, ['@cf/qwen/qwen2.5-coder-32b-instruct', '@cf/openai/gpt-oss-120b']);
  assert.ok(!specialists.includes('@cf/moonshotai/kimi-k2.7-code'));
  // The small code model never sits in the general Council; gpt-oss-120b is
  // both a general reviewer and the large free code model (GLM-5.3 Flash is paid).
  assert.ok(!pool.list({ capability: 'GENERAL' }).some(p => p.modelId === '@cf/qwen/qwen2.5-coder-32b-instruct'));
  assert.ok(!specialists.includes('@cf/zai-org/glm-5.3-flash'));
  assert.ok(standardRegistry.list().filter(m => (m.capabilities || []).includes('CODE_LARGE')).length === 1);
});

test('verified terminal statuses are counted as deliveries while queued work is not', () => {
  for (const status of ['COMPLETED', 'DONE', 'DONE_VERIFIED', 'VERIFIED', 'ACCEPTED']) {
    const report = auditDevelopment({ now: NOW, jobs: [job({ status })] });
    assert.equal(report.summary.completed, 1, status);
    assert.ok(!report.findings.some(f => f.code === 'NO_DELIVERY_THIS_WEEK'), status);
  }
  const queued = auditDevelopment({ now: NOW, jobs: [job({ status: 'QUEUED' })] });
  assert.equal(queued.summary.completed, 0);
  assert.ok(queued.findings.some(f => f.code === 'NO_DELIVERY_THIS_WEEK'));
});

test('a successful code-model probe cancels its pending timeout', async t => {
  const oldSet = globalThis.setTimeout, oldClear = globalThis.clearTimeout, handles = [];
  globalThis.setTimeout = (callback, delay) => {
    const handle = { callback, delay, cleared: false };
    handles.push(handle);
    return handle;
  };
  globalThis.clearTimeout = handle => { handle.cleared = true; };
  t.after(() => { globalThis.setTimeout = oldSet; globalThis.clearTimeout = oldClear; });
  const registry = { list: () => [{ id: 'test-coder', capabilities: ['CODE_SPECIALIST'] }] };
  const result = await probeCodeModels({
    AI: { run: async () => ({ response: 'function sumEven(list) { return list.filter(n => n % 2 === 0).reduce((a, n) => a + n, 0); }' }) }
  }, { registry, timeoutMs: 250 });
  assert.equal(result[0].passed, true);
  assert.equal(handles.length, 1);
  assert.equal(handles[0].cleared, true);
});

test('a timed-out code-model probe fails and clears its timer', async t => {
  const oldSet = globalThis.setTimeout, oldClear = globalThis.clearTimeout, handles = [];
  globalThis.setTimeout = (callback, delay) => {
    const handle = { callback, delay, cleared: false };
    handles.push(handle);
    queueMicrotask(callback);
    return handle;
  };
  globalThis.clearTimeout = handle => { handle.cleared = true; };
  t.after(() => { globalThis.setTimeout = oldSet; globalThis.clearTimeout = oldClear; });
  const registry = { list: () => [{ id: 'unresponsive-coder', capabilities: ['CODE_SPECIALIST'] }] };
  const result = await probeCodeModels({
    AI: { run: () => new Promise(() => {}) }
  }, { registry, timeoutMs: 250 });
  assert.equal(result.length, 1);
  assert.equal(result[0].passed, false);
  assert.equal(result[0].error, 'PROBE_TIMEOUT');
  assert.equal(handles.length, 1);
  assert.equal(handles[0].cleared, true);
});

test('MEL-AUDIT-02 records a durable weekly report and deduplicated findings without dispatching a repair', async t => {
  const { sqliteD1 } = await import('./helpers/sqlite-d1.mjs');
  const db = sqliteD1();
  t.after(() => db.close());
  const rows = [
    job({ id: 'delivered', status: 'COMPLETED', optional_context: { roadmap_id: 'MEL-A' } }),
    job({ id: 'blocked', status: 'WAITING_DEPENDENCY', optional_context: { roadmap_id: 'MEL-B' } }),
    ...Array.from({ length: 4 }, (_, i) => job({ id: 'retry-' + i, status: 'FAILED', optional_context: { roadmap_id: 'MEL-C' } })),
  ];
  const report = auditDevelopment({ now: NOW, jobs: [...rows, rows[0]] });
  assert.equal(report.summary.jobs, 6, 'a duplicated snapshot must not count as another attempt');
  assert.equal(report.summary.completed, 1);
  assert.equal(report.summary.blocked, 1);
  assert.equal(report.summary.repeated_objectives, 1);
  assert.ok(report.findings.some(f => f.code === 'MISSION_LOOP'));
  assert.equal(report.findings.some(f => f.code === 'NO_DELIVERY_THIS_WEEK'), false);
  const repeat = { ...report, findings: [...report.findings, report.findings[0]] };
  const first = await persistWeeklyDevelopmentAudit(db, repeat, { now: NOW });
  const second = await persistWeeklyDevelopmentAudit(db, repeat, { now: NOW + 3000 });
  assert.equal(first.persisted, true);
  assert.equal(first.week_start, second.week_start);
  const saved = await db.prepare('SELECT report_json FROM mel_development_audit_reports').all();
  assert.equal(saved.results.length, 1);
  assert.equal(JSON.parse(saved.results[0].report_json).summary.blocked, 1);
  const findings = await db.prepare('SELECT code,detail FROM mel_development_audit_findings').all();
  assert.equal(findings.results.length, new Set(report.findings.map(f => JSON.stringify([f.code, f.detail]))).size);
  const jobs = await db.prepare('SELECT COUNT(*) AS total FROM dev_jobs').first().catch(() => ({ total: 0 }));
  assert.equal(Number(jobs?.total || 0), 0, 'recording audit evidence must not enqueue jobs');
});

test('MEL-AUDIT-02 refresh removes stale findings without creating a new mission', async t => {
  const { sqliteD1 } = await import('./helpers/sqlite-d1.mjs');
  const db = sqliteD1();
  t.after(() => db.close());
  const first = { findings: [{ code: 'MISSION_LOOP', detail: 'MEL-AUDIT-02 x6' }, { code: 'JOBS_STALLED', detail: 'historical' }], summary: { state: 'unresolved' } };
  const second = { findings: [{ code: 'REPAIR_VERIFIED', detail: 'MEL-AUDIT-02' }, { code: 'REPAIR_VERIFIED', detail: 'MEL-AUDIT-02' }], summary: { state: 'resolved' } };
  const a = await persistWeeklyDevelopmentAudit(db, first, { now: NOW });
  const b = await persistWeeklyDevelopmentAudit(db, second, { now: NOW + 1000 });
  assert.equal(a.week_start, b.week_start);
  assert.equal(b.findings_recorded, 1);
  const findings = await db.prepare('SELECT code,detail FROM mel_development_audit_findings ORDER BY code').all();
  assert.deepEqual(findings.results, [{ code: 'REPAIR_VERIFIED', detail: 'MEL-AUDIT-02' }]);
  const report = await db.prepare('SELECT report_json FROM mel_development_audit_reports').first();
  assert.equal(JSON.parse(report.report_json).summary.state, 'resolved');
  await persistWeeklyDevelopmentAudit(db, { ...second, findings: [] }, { now: NOW + 2000 });
  assert.equal((await db.prepare('SELECT code FROM mel_development_audit_findings').all()).results.length, 0);
  const stored = await db.prepare('SELECT COUNT(*) AS count FROM mel_development_audit_reports').first();
  assert.equal(stored.count, 1);
});
